head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.checked1 = false;
scwin.chkflag = 0;
scwin.gLdMktTp;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trv_rsnclss_OnCheckBoxClick
 * @description trv rsnclss On Check Box Click 처리
 * @param {*} check check
 * @param {Number} index index
 * @param {*} level level
 * @returns {void}
 * @hidden N
 */
scwin.trv_rsnclss_OnCheckBoxClick = function(check, index, level) {
    try {
        if (check === true) {
            dts_Rsnclss_list.setCellData(index, "CHK_FLAG", 1);
        } else {
            dts_Rsnclss_list.setCellData(index, "CHK_FLAG", 0);
        }
        let vFormUpclssCd = dts_Rsnclss_list.getCellData(index, "FORM_UPCLSS_CD");
        let vRrsClssCd = dts_Rsnclss_list.getCellData(index, "RSN_CLSS_CD");
        // alert('FORM_UPCLSS_CD = '+vFormUpclssCd+',  rsn_cd => '+ vRrsClssCd+' , level =' + level);

        // 선택한 서식대분류 하위를 모두 체크하기
        if (level === '1' && check === true) {
            dts_Rsnclss_list.setBroadcast(false);
            for (let i = index + 1; i <= dts_Rsnclss_list.getRowCount(); i++) {
                if (vFormUpclssCd === dts_Rsnclss_list.getCellData(i, "FORM_UPCLSS_CD")) {
                    trv_rsnclss.checkByIndex(i, true);
                    dts_Rsnclss_list.setCellData(i, "CHK_FLAG", 1);
                } else {
                    break;
                }
            }
            dts_Rsnclss_list.setBroadcast(true, true);
        } else if (level === '1' && check === false) {
            // 선택해제한 서식대분류 하위를 모두 체크해제하기
            dts_Rsnclss_list.setBroadcast(false);
            for (let i = index + 1; i <= dts_Rsnclss_list.getRowCount(); i++) {
                if (vFormUpclssCd === dts_Rsnclss_list.getCellData(i, "FORM_UPCLSS_CD")) {
                    trv_rsnclss.checkByIndex(i, false);
                    dts_Rsnclss_list.setCellData(i, "CHK_FLAG", 0);
                } else {
                    break;
                }
            }
            dts_Rsnclss_list.setBroadcast(true, true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15001.trv_rsnclss_OnCheckBoxClick" });
    }
};

/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15001.img_close_onclick" });
    }
};

/**
 * @method
 * @name img_confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_confirm_onclick = async function() {
    try {
        scwin.confirm();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15001.img_confirm_onclick" });
    }
};

/**
 * @method
 * @name dts_Rsnclss_list_OnLoadCompleted
 * @description dts_Rsnclss_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Rsnclss_list_OnLoadCompleted = function(rowcount) {
    try {
        scwin.checkPreSelected();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15001.dts_Rsnclss_list_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_SelectedAll_onclick
 * @description 「전체선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SelectedAll_onclick = function() {
    try {
        scwin.On_SetCheckedBox();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15001.btn_SelectedAll_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const pvd = scwin.getProvider();
    let Temp0 = "";
    if (pvd !== null) {
        Temp0 = pvd.split("&")[0];
        scwin.gLdMktTp = Temp0.split("=")[1];
    } else {
        scwin.gLdMktTp = js_market;
    }

    // 공시사유분류 트리에 셋팅하기
    const sbmOptions = {
        id : "sbm_dts_Rsnclss_list",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Rsnclss_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    const url = frame.srcUrl;
    const arr = url.split("?")[1];
    if (arr !== null) {
        return (arr.length >= 1 ? arr : undefined);
    } else {
        return null;
    }
};

/**
 * @method
 * @name checkPreSelected
 * @description opener에 셋팅된 값을 트리에 체크하기
 * @returns {void}
 * @hidden N
 */
scwin.checkPreSelected = function() {
    // alert('시작' + frame.opener.txb_rsn_cnt.value);
    let vFormUpclssCd;
    let vRrsClssCd;

    // 셋팅된것이 있을때만...
    if (frame.opener.txb_rsn_cnt.getValue() > 0) {
        dts_Rsnclss_list.setBroadcast(false);
        for (let i = 1; i <= frame.opener.dts_Dscl_Cond.getRowCount(); i++) {
            vFormUpclssCd = frame.opener.dts_Dscl_Cond.getCellData(i, "FORM_UPCLSS_CD");
            vRrsClssCd = frame.opener.dts_Dscl_Cond.getCellData(i, "RSN_CLSS_CD");
            for (let h = 1; h <= dts_Rsnclss_list.getRowCount(); h++) {
                // 트리에 체크하기

                // alert(vFormUpclssCd +'='+ dts_Rsnclss_list.NameValue(h ,"FORM_UPCLSS_CD")
                //    + ' && '+  vRrsClssCd +'='+  dts_Rsnclss_list.NameValue(h ,"RSN_CLSS_CD") );

                if (vFormUpclssCd === dts_Rsnclss_list.getCellData(h, "FORM_UPCLSS_CD") &&
                    vRrsClssCd === dts_Rsnclss_list.getCellData(h, "RSN_CLSS_CD")) {
                    dts_Rsnclss_list.setCellData(h, "CHK_FLAG", 1);
                    trv_rsnclss.checkByIndex(h, true);
                    trv_rsnclss.expandNode(h, true);
                }
            }
        }
        dts_Rsnclss_list.setBroadcast(true, true);
    }
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name confirm
 * @description opener에 값 선택된 값 전달.
 * @returns {void}
 * @hidden N
 */
scwin.confirm = function() {
    let total = 0;
    for (let i = 1; i <= dts_Rsnclss_list.getRowCount(); i++) {
        let chk = dts_Rsnclss_list.getCellData(i, "CHK_FLAG");

        // alert('chk='+chk +'====='+ dts_Rsnclss_list.NameValue(i ,"DISCLS_RSN_CLSS_NM")) ;
        if (chk === "T" || chk === "1") {
            total++;
        }
    }

    /*
    if (total == 0) {
    	alert("공시사유분류를  선택하세요.");
    	return;
    }
     */

    frame.opener.txb_rsn_cnt.setValue(total);

    // 부모창에 셋팅하기
    frame.opener.dts_Dscl_Cond.ClearData();
    let j = 1;
    dts_Dscl_Cond.setBroadcast(false);
    for (let k = 1; k <= dts_Rsnclss_list.getRowCount(); k++) {
        let chk = dts_Rsnclss_list.getCellData(k, "CHK_FLAG");
        if (chk === "T" || chk === "1") {
            frame.opener.dts_Dscl_Cond.AddRow();
            frame.opener.dts_Dscl_Cond.setCellData(j, "FORM_UPCLSS_CD", dts_Rsnclss_list.getCellData(k, "FORM_UPCLSS_CD"));
            frame.opener.dts_Dscl_Cond.setCellData(j, "RSN_CLSS_CD", dts_Rsnclss_list.getCellData(k, "RSN_CLSS_CD"));
            j++;
        }
    }
    dts_Dscl_Cond.setBroadcast(true, true);
};

/**
 * @method
 * @name On_SetCheckedBox
 * @description 전체선택 및 전체 해제 하기
 * @returns {void}
 * @hidden N
 */
scwin.On_SetCheckedBox = function() {
    if (scwin.checked1 === true) {
        scwin.checked1 = false;
        scwin.chkflag = 0;
        btn_SelectedAll.setValue("전체 선택");
    } else {
        scwin.checked1 = true;
        scwin.chkflag = 1;
        btn_SelectedAll.setValue("전체 해제");
    }
    dts_Rsnclss_list.setBroadcast(false);
    for (let i = 1; i <= dts_Rsnclss_list.getRowCount(); i++) {
        trv_rsnclss.checkByIndex(i, scwin.checked1);
        dts_Rsnclss_list.setCellData(i, "CHK_FLAG", scwin.chkflag);
    }
    dts_Rsnclss_list.setBroadcast(true, true);
};
